import{_ as i,C as n,o as s,c as o,a6 as r,E as l,j as t,a as d}from"./chunks/framework.CKIbuWFA.js";const y=JSON.parse('{"title":"Read and inspect the LIVE feed","description":"","frontmatter":{"title":"Read and inspect the LIVE feed","docId":"user.live.feed","translationKey":"user.live.feed","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4830f0a02244f46bfefb9b37c09d96c969688d022a0df90359c96c3e359af147","translationRevision":"4830f0a02244f46bfefb9b37c09d96c969688d022a0df90359c96c3e359af147","order":20},"headers":[],"relativePath":"en/user/live/feed.md","filePath":"en/user/live/feed.md","lastUpdated":1794611623000}'),c={name:"en/user/live/feed.md"};function h(p,e,u,f,v,g){const a=n("DemoFrame");return s(),o("div",null,[e[0]||(e[0]=r('<h1 id="read-and-inspect-the-live-feed" tabindex="-1">Read and inspect the LIVE feed <a class="header-anchor" href="#read-and-inspect-the-live-feed" aria-label="Permalink to &quot;Read and inspect the LIVE feed {#read-and-inspect-the-live-feed}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Find an event, inspect its fields and distinguish a paused display from a disconnected room. Start with a <a href="./connections.html">LIVE connection</a>, or use events already present in the current feed. The feed is a bounded working view, not a complete recording of a broadcast.</p><h2 id="inspect-activity" tabindex="-1">Inspect activity <a class="header-anchor" href="#inspect-activity" aria-label="Permalink to &quot;Inspect activity {#inspect-activity}&quot;">​</a></h2><ol><li>Open <strong>Live feed</strong> and confirm the active creator in the connection status.</li><li>Choose an event filter: all events, chat, gifts, likes, follows, joins or other social activity. Combine it with search to find an author, message, gift name or exact gift ID.</li><li>Select <strong>Pause</strong> to stop automatic scrolling while you read. Events can continue arriving and the unread count can increase. This control does not disconnect TikTok or suspend automations.</li><li>Select an event to open its inspector. Read the event type and available details before choosing automation fields. Not every event carries chat text, gift information or a viewer identity.</li><li>Select a viewer&#39;s name or avatar to inspect their tracked profile. Use the inspector toggle if the details panel is hidden.</li><li>Select <strong>Resume</strong> or the unread-event jump button to return to incoming activity. Clear the search and select all events when checking whether activity is arriving.</li></ol><p>Use the labeled controls with keyboard focus where possible. Pausing scrolling helps when movement makes reading difficult. A missing avatar has an initials fallback; a picture is not needed to identify a viewer.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Filtering and inspection are available. During heavy traffic, the interface can show a limited rendering window and report dropped UI events. These indicators describe the display; do not use its visible row count as an accounting total. <a href="./../points/statistics.html">Analytics</a> queries persisted aggregates separately.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>If the feed is empty, remove filters, resume scrolling and check connection status. A quiet room may be healthy. Reconnecting to the same creator retains context; switching creator changes it. <strong>Clear</strong> empties the working feed and does not reset points or analytics. Investigate loss indicators through <a href="./../preferences/troubleshooting.html">diagnostics</a>, without assuming all missing display rows are missing upstream events.</p>',10)),l(a,{scenario:"feed",locale:"en",title:"Demo: feed"}),e[1]||(e[1]=t("h2",{id:"operational-details",tabindex:"-1"},[d("Operational details "),t("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "Operational details {#operational-details}"'},"​")],-1)),e[2]||(e[2]=t("p",null,"This version retains up to 300 displayed events and stages up to 900 while presentation waits. Retention evicts the oldest non-gift row first; gifts are evicted only when no other types remain. An older gift can therefore outlast a newer chat. Pausing scrolling does not stop ingestion or guarantee retention. Filters cannot restore evicted rows; a loss warning is evidence of an incomplete view, not permission to replay points or actions.",-1))])}const b=i(c,[["render",h]]);export{y as __pageData,b as default};
